'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['isRightTriangle']);
const { isRightTriangle } = api;

for (const sides of [[3, 4, 5], [5, 3, 4], [4, 5, 3], [5, 12, 13], [1, 1, 1]]) {
  const snapshot = sides.slice();
  const expected = sides[0] === 1 ? false : true;
  assert.strictEqual(isRightTriangle(sides), expected);
  assert.deepStrictEqual(sides, snapshot);
}
assert.strictEqual(isRightTriangle([6, 8, 10]), true);
assert.strictEqual(isRightTriangle([2, 3, 4]), false);
assert.strictEqual(isRightTriangle([1, 1, 1]), false);

const sparse = new Array(3);
sparse[0] = 3;
sparse[2] = 5;
for (const value of [
  null, undefined, '3,4,5', {}, [], [3, 4], [3, 4, 5, 6], sparse,
  [0, 4, 5], [-3, 4, 5], [3.5, 4, 5], ['3', 4, 5], [3n, 4, 5],
  [Number.MAX_SAFE_INTEGER + 1, 1, 1], [NaN, 4, 5], [Infinity, 4, 5]
]) {
  assert.strictEqual(isRightTriangle(value), false);
}

